{"cmd":"python3 << 'EOF'
import json

chart_spec = {
    "title": "Crime Type Association Network (|corr| >= 0.40)",
    "mark": "network",
    "layout": {
        "type": "circular",
        "node_order": ["Murder", "Rape_Revised", "Robbery", "Assault", "Burglary", "Larceny", "Vehicle_Theft"],
        "start": "top",
        "direction": "anticlockwise"
    },
    "nodes": {
        "values": ["Murder", "Rape_Revised", "Robbery", "Assault", "Burglary", "Larceny", "Vehicle_Theft"],
        "fill": "#F2F2F2",
        "stroke": "#333333"
    },
    "edges": {
        "data": "derived_edges.csv",
        "source": "source",
        "target": "target",
        "weight": "corr",
        "threshold_abs_corr": 0.4,
        "undirected": True,
        "self_loops": False
    },
    "edge_encoding": {
        "color": {
            "field": "sign",
            "positive": "#D7191C",
            "negative": "#2C7BB6"
        },
        "width": {
            "field": "strength_bin",
            "0.40-0.54": 1.3,
            "0.55-0.69": 2.6,
            "0.70+": 4.0
        }
    }
}

with open('chart_spec.json', 'w') as f:
    json.dump(chart_spec, f, indent=2)

print(json.dumps(chart_spec, indent=2))
EOF"}

